def порядок_круга(позиции: list, *, сейчас: float) -> tuple[list, list]:
    """(срочные, хвост). Срочные -- те, кому пора продавать, по близости срока.

    Чистая функция: ни сети, ни состояния. Срок берётся тем же
    срок_продажи_ts, которым круг считает сон, -- двух правд о сроке быть не
    должно. Позиция без срока попадает в хвост: продавать её пока нечем.
    """
    срочные, хвост = [], []
    for поз in (позиции or []):
        if not isinstance(поз, dict):
            continue
        т = срок_продажи_ts(поз)
        if isinstance(т, (int, float)) and float(т) <= float(сейчас):
            срочные.append((float(т), поз))
        else:
            хвост.append((float(т) if isinstance(т, (int, float)) else float("inf"),
                           поз))
    срочные.sort(key=lambda п: п[0])
    хвост.sort(key=lambda п: п[0])
    return [п for _, п in срочные], [п for _, п in хвост]
